function getSessionKey(): Buffer {
  const secret = process.env.SESSION_SECRET;
  if (!secret) {
    throw new Error("SESSION_SECRET environment variable is required.");
  }
  return crypto.createHash("sha256").update(secret).digest();
}

export interface SessionPayload {
  userId: number;
  idCompania: number;
  rol: "Administrador" | "Profesional";
}

export function createSessionToken(payload: SessionPayload): string {
  const body = JSON.stringify({ ...payload, exp: Date.now() + SESSION_TTL_MS });
  const encoded = Buffer.from(body, "utf8").toString("base64url");
  const signature = crypto.createHmac("sha256", getSessionKey()).update(encoded).digest("base64url");
  return `${encoded}.${signature}`;
}

export function verifySessionToken(token: string): SessionPayload | null {
  const [encoded, signature] = token.split(".");
  if (!encoded || !signature) return null;

  const expectedSignature = crypto.createHmac("sha256", getSessionKey()).update(encoded).digest("base64url");
  const givenBuf = Buffer.from(signature);
  const expectedBuf = Buffer.from(expectedSignature);
  if (givenBuf.length !== expectedBuf.length || !crypto.timingSafeEqual(givenBuf, expectedBuf)) {
    return null;
  }

  try {
    const body = JSON.parse(Buffer.from(encoded, "base64url").toString("utf8"));
    if (typeof body.exp !== "number" || Date.now() > body.exp) return null;
    if (typeof body.userId !== "number" || typeof body.idCompania !== "number") return null;
    return { userId: body.userId, idCompania: body.idCompania, rol: body.rol };
  } catch {
    return null;
  }
}

export function isBcryptHash(value: string): boolean {
  return BCRYPT_HASH_PATTERN.test(value);
}

export function passwordMatches(stored: string, input: string): boolean {
  if (isBcryptHash(stored)) {
    return bcrypt.compareSync(input, stored);
  }
  return stored === input;
}

export function hashPassword(plain: string): string {
  return bcrypt.hashSync(plain, 10);
}

export function generateNumericPassword(digits: number): string {
  const min = Math.pow(10, digits - 1);
  const max = Math.pow(10, digits) - 1;
  return crypto.randomInt(min, max + 1).toString();
}

export function isSaasAdmin(session: SessionPayload | null | undefined): boolean {
  return !!session && session.idCompania === SAAS_ADMIN_COMPANY_ID && session.rol === "Administrador";
}

export function readCookie(cookieHeader: string | undefined, name: string): string | null {
  if (!cookieHeader) return null;
  for (const part of cookieHeader.split(";")) {
    const eq = part.indexOf("=");
    if (eq === -1) continue;
    if (part.slice(0, eq).trim() === name) {
      return decodeURIComponent(part.slice(eq + 1).trim());
    }
  }
  return null;
}

export function serializeSessionCookie(value: string, maxAgeSeconds: number): string {
  return `${SESSION_COOKIE}=${encodeURIComponent(value)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAgeSeconds}`;
}

function aRgb(hex: string): { r: number; g: number; b: number } | null {
  const limpio = String(hex || "").trim().replace(/^#/, "");
  const completo = limpio.length === 3
    ? limpio.split("").map(c => c + c).join("")
    : limpio;
  if (!/^[0-9a-fA-F]{6}$/.test(completo)) return null;
  return {
    r: parseInt(completo.slice(0, 2), 16),
    g: parseInt(completo.slice(2, 4), 16),
    b: parseInt(completo.slice(4, 6), 16)
  };
}

function luminancia(hex: string): number | null {
  const rgb = aRgb(hex);
  if (!rgb) return null;
  const canal = (v: number) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * canal(rgb.r) + 0.7152 * canal(rgb.g) + 0.0722 * canal(rgb.b);
}

function razonContraste(l1: number, l2: number): number {
  const claro = Math.max(l1, l2);
  const oscuro = Math.min(l1, l2);
  return (claro + 0.05) / (oscuro + 0.05);
}

export function textoSobre(hexFondo: string): string {
  const l = luminancia(hexFondo);
  if (l == null) return NEGRO_TEXTO;
  const contrasteBlanco = razonContraste(l, luminancia(BLANCO_TEXTO)!);
  const contrasteNegro = razonContraste(l, luminancia(NEGRO_TEXTO)!);
  return contrasteNegro >= contrasteBlanco ? NEGRO_TEXTO : BLANCO_TEXTO;
}

export function tinte(hex: string, alpha: number): string {
  const rgb = aRgb(hex);
  if (!rgb) return "rgba(148,163,184,0.12)";
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
}

export function colorMarca(hex: string | null | undefined, respaldo: string): string {
  return aRgb(hex || "") ? String(hex) : respaldo;
}

function getKey(): Buffer {
  const hex = process.env.ENCRYPTION_KEY;
  if (!hex || hex.length !== 64) {
    throw new Error("ENCRYPTION_KEY environment variable is required and must be a 64-character hex string (32 bytes).");
  }
  return Buffer.from(hex, "hex");
}

export function encryptSecret(plain: string): string {
  const key = getKey();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
  const encrypted = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return `${iv.toString("hex")}:${authTag.toString("hex")}:${encrypted.toString("hex")}`;
}

export function decryptSecret(cipherText: string): string {
  const parts = cipherText.split(":");
  if (parts.length !== 3) {
    throw new Error("Configura una contraseña SMTP real desde Ajustes de Empresa.");
  }
  const [ivHex, authTagHex, dataHex] = parts;
  const key = getKey();
  const iv = Buffer.from(ivHex, "hex");
  const authTag = Buffer.from(authTagHex, "hex");
  const encrypted = Buffer.from(dataHex, "hex");
  const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(authTag);
  const decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);
  return decrypted.toString("utf8");
}

