  diasEntrenamiento: number
): number {
  return (tmb * factorActividadDescanso * diasDescanso + tmb * factorActividadEntreno * diasEntrenamiento) / 7;
}

export function aplicarPorcentaje(promedio: number, direccion: DireccionPrescripcion, porcentaje: number): number {
  if (direccion === 'DEFICIT') return promedio * (1 - porcentaje / 100);
  if (direccion === 'SUPERAVIT') return promedio * (1 + porcentaje / 100);
  return promedio;
}

export function fechaHoraCR(fecha: Date = new Date()): string {
  return new Date(fecha.getTime() - OFFSET_CR_MS).toISOString().replace(/\.\d+Z$/, "") + "-06:00";
}

export function fechaCR(fecha: Date = new Date()): string {
  return fechaHoraCR(fecha).slice(0, 10);
}

export function sumarDiasCR(fechaYmd: string, dias: number): string {
  const d = new Date(`${fechaYmd}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + dias);
  return d.toISOString().slice(0, 10);
}

export function loadGoogleMapsScript(apiKey: string): Promise<void> {
  if ((window as any).google?.maps) return Promise.resolve();
  if (loadPromise) return loadPromise;

  loadPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(apiKey)}&libraries=places`;
    script.async = true;
    script.onload = () => resolve();
    script.onerror = () => reject(new Error('No se pudo cargar Google Maps.'));
    document.head.appendChild(script);
  });

  return loadPromise;
}

